import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Generic Pratt Parser — Grammar Data Replaces Per-Construct Branches","description":"","frontmatter":{"title":"Generic Pratt Parser — Grammar Data Replaces Per-Construct Branches","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Proposed — the five parser special cases and the literal heuristic are grammar data.","refs":["ADR-0044"]},"headers":[],"relativePath":"handl/project/adrs/0053-generic-pratt-parser.md","filePath":"vendored/handl/project/adrs/0053-generic-pratt-parser.md"}`),a={name:`handl/project/adrs/0053-generic-pratt-parser.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0053-generic-pratt-parser-—-grammar-data-replaces-per-construct-branches" tabindex="-1">ADR-0053: Generic Pratt Parser — Grammar Data Replaces Per-Construct Branches <a class="header-anchor" href="#adr-0053-generic-pratt-parser-—-grammar-data-replaces-per-construct-branches" aria-label="Permalink to “ADR-0053: Generic Pratt Parser — Grammar Data Replaces Per-Construct Branches”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong><code>TokenKindDef.literal: Option&lt;LiteralKind&gt;</code></strong> replaces the <code>kind_id.contains(...)</code> heuristics in <code>atom_payload</code> with typed literal dispatch.</li><li><strong><code>AstShapeRef.child_separators: Vec&lt;ChildSeparator&gt;</code></strong> replaces the <code>if/then/else</code> and <code>x = y in body</code> separator hardcoding.</li><li><strong><code>DelimitedShape.open_is_operator_token: bool</code></strong> — the open delimiter is the prefix/infix token itself; replaces the <code>array</code>/<code>object</code>/<code>paren</code>/<code>call</code> hardcoding.</li><li><strong><code>DelimitedShape.flatten: bool</code></strong> splices elements into the parent&#39;s children, keeping <code>call</code> flat for every eval engine.</li><li><strong><code>DelimitedShape.rest_token: Option&lt;String&gt;</code></strong> replaces the <code>token.ellipsis</code> special case for rest/spread elements.</li><li><strong>The infix path consults <code>delimited</code></strong>, mirroring the prefix path — the hardcoded <code>call</code> branch disappears.</li><li><strong>Parser desugars move to a data-driven post-parse pass.</strong> <code>if</code> becomes a real AST node (arity 3); the <code>if → match</code> rewrite is a transform (ADR-0094), not parser code.</li><li><strong>Contextual forms (<code>match</code>, <code>data</code>, <code>from</code>) are closed by grammar data</strong> — per-child binding powers and trailing token steps, all <code>serde</code>-defaulted so third-party grammar rows are unaffected.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The Pratt engine still special-cased each construct — five branches plus a substring heuristic for literals — so every new syntax meant engine code. ADR-0044 (language as data) requires grammar rows to carry that knowledge; this ADR removes the last per-construct branches and moves the parser&#39;s desugars to the transform engine.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Turing-complete grammar description</strong> — list comprehensions and multi-block constructs fall outside one <code>DelimitedShape</code> and stay parser code.</li><li><strong>Keep desugars in the parser</strong> — they move to the data-driven transform pass (ADR-0094).</li><li><strong>Break third-party grammar rows</strong> — every new field is <code>serde</code>-defaulted.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>expression_inner</code> has no string literals; <code>atom_payload</code>, <code>parse_delimited_block</code> and <code>consume</code> are the only sub-routines.</li><li>Grammar data grows and becomes the review surface; parser code shrinks.</li><li>Contextual forms were closed by amendment without further engine changes.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>engine-parse-pratt/</code> — the generic parser crate.</li><li><code>kit-prelude-lang/crates/handl-kit-prelude-lang/data/grammar.yaml</code> — the rows that now carry the knowledge.</li><li>Parser tests: <code>tests/</code> in <code>engine-parse-pratt</code>.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The five fields, before/after code shape, amendments and the scope boundary: <a href="./../design/0053-generic-pratt-parser.html"><code>design/0053-generic-pratt-parser.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};